              + (state.missing ? ' · <span style="color:var(--ks-warn)">not found — showing defaults.</span>' : '')
              + ' · ' + esc(String(total)) + ' keys'
              + (nn ? ' · <span style="color:var(--ks-warn)">' + nn + ' modified</span>' : ' · no changes');
